//! Differential ratchet for
//! `src/engine/battleScriptSetminimizeOpcode.ts`. Expected complete projected
//! results and the exact gated role error are generated by invoking the
//! canonical TypeScript opcode handler; regenerate with `node
//! --experimental-strip-types
//! core-rs/tools/gen-battle-script-setminimize-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_setminimize::{
    apply_battle_script_setminimize, BattleScriptSetminimizeBattlerState,
    BattleScriptSetminimizeRoles, BattleScriptSetminimizeRules, BATTLE_SCRIPT_HITMARKER_OBEYS,
    BATTLE_SCRIPT_SETMINIMIZE_BATTLERS, BATTLE_SCRIPT_SETMINIMIZE_BATTLER_COUNT,
    BATTLE_SCRIPT_STATUS3_MINIMIZED,
};
use factory_core::battle_script_setminimize_vectors_gen::{
    BattleScriptSetminimizeVectorCase, BattleScriptSetminimizeVectorState,
    BATTLE_SCRIPT_SETMINIMIZE_BATTLER_DOMAIN, BATTLE_SCRIPT_SETMINIMIZE_BRANCH_CENSUS,
    BATTLE_SCRIPT_SETMINIMIZE_CASES, BATTLE_SCRIPT_SETMINIMIZE_CATEGORY_CENSUS,
    BATTLE_SCRIPT_SETMINIMIZE_DOMAIN_CENSUS, BATTLE_SCRIPT_SETMINIMIZE_HIT_MARKER_EDGE_DOMAIN,
    BATTLE_SCRIPT_SETMINIMIZE_MINIMIZED_INPUT_DOMAIN,
    BATTLE_SCRIPT_SETMINIMIZE_STATUS3_EDGE_DOMAIN, BATTLE_SCRIPT_SETMINIMIZE_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptSetminimizeVectorState) -> BattleScriptSetminimizeRules {
    BattleScriptSetminimizeRules {
        battlers: value
            .status3
            .map(|status3| BattleScriptSetminimizeBattlerState { status3 }),
        hit_marker: value.hit_marker,
        selector_roles: BattleScriptSetminimizeRoles { attacker: value.attacker },
    }
}

fn vector_state(value: BattleScriptSetminimizeRules) -> BattleScriptSetminimizeVectorState {
    BattleScriptSetminimizeVectorState {
        status3: value.battlers.map(|battler| battler.status3),
        hit_marker: value.hit_marker,
        attacker: value.selector_roles.attacker,
    }
}

#[test]
fn complete_projected_outputs_and_gate_ordered_error_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_SETMINIMIZE_CASES.len(), 51);
    for (case_index, case) in BATTLE_SCRIPT_SETMINIMIZE_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptSetminimizeVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut actual_result = Ok(input);
    for _ in 0..case.applications {
        actual_result = actual_result.and_then(|current| apply_battle_script_setminimize(&current));
    }

    match (actual_result, case.expected, case.expected_error) {
        (Ok(actual), Some(expected), None) => {
            assert_eq!(
                input, before,
                "case {case_index} {}: native transformation mutated input",
                case.label,
            );
            assert_eq!(
                vector_state(actual),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
            assert_eq!(
                actual.hit_marker, before.hit_marker,
                "case {case_index} {}: changed hitMarker",
                case.label,
            );
            assert_eq!(
                actual.selector_roles, before.selector_roles,
                "case {case_index} {}: changed attacker role binding",
                case.label,
            );

            if before.hit_marker & BATTLE_SCRIPT_HITMARKER_OBEYS == 0 {
                assert_eq!(
                    actual, before,
                    "case {case_index} {}: OBEYS-clear projection was not a complete no-op",
                    case.label,
                );
                return;
            }

            let attacker = before.selector_roles.attacker.unwrap_or_else(|| {
                panic!(
                    "case {case_index} {}: OBEYS-set success vector has no attacker",
                    case.label
                )
            });
            for battler in BATTLE_SCRIPT_SETMINIMIZE_BATTLERS {
                if battler != attacker {
                    assert_eq!(
                        actual.battlers[battler.index()],
                        before.battlers[battler.index()],
                        "case {case_index} {}: changed non-attacker battler {}",
                        case.label,
                        battler.as_u8(),
                    );
                }
            }
            assert_eq!(
                actual.battlers[attacker.index()].status3,
                before.battlers[attacker.index()].status3 | BATTLE_SCRIPT_STATUS3_MINIMIZED,
                "case {case_index} {}: did not OR minimized into attacker",
                case.label,
            );
            assert_eq!(
                actual.battlers[attacker.index()].status3 & !BATTLE_SCRIPT_STATUS3_MINIMIZED,
                before.battlers[attacker.index()].status3 & !BATTLE_SCRIPT_STATUS3_MINIMIZED,
                "case {case_index} {}: changed attacker status3 unrelated bits",
                case.label,
            );

            let repeated = apply_battle_script_setminimize(&actual).unwrap_or_else(|error| {
                panic!(
                    "case {case_index} {}: idempotence application errored: {error}",
                    case.label
                )
            });
            assert_eq!(
                repeated, actual,
                "case {case_index} {}: setting minimized is not idempotent",
                case.label,
            );
        }
        (Err(error), None, Some(expected_error)) => {
            assert_eq!(
                input, before,
                "case {case_index} {}: failed transformation mutated input",
                case.label,
            );
            assert_eq!(
                error.to_string(),
                expected_error,
                "case {case_index} {}: exact gated missing-attacker error",
                case.label,
            );
        }
        (result, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: result={result:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

#[test]
fn matrix_covers_every_attacker_both_gates_and_minimized_clear_set_inputs() {
    let matrix = BATTLE_SCRIPT_SETMINIMIZE_CASES
        .iter()
        .filter(|case| case.category == "attacker-gate-minimized-matrix")
        .collect::<Vec<_>>();
    assert_eq!(matrix.len(), 16);

    let domain = matrix
        .iter()
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("matrix case {} has no attacker", case.label));
            (
                attacker.as_u8(),
                case.initial.hit_marker & BATTLE_SCRIPT_HITMARKER_OBEYS != 0,
                case.initial.status3[attacker.index()] & BATTLE_SCRIPT_STATUS3_MINIMIZED != 0,
            )
        })
        .collect::<BTreeSet<_>>();
    let expected = (0_u8..4)
        .flat_map(|attacker| {
            [false, true].into_iter().flat_map(move |obeys| {
                [false, true]
                    .into_iter()
                    .map(move |minimized| (attacker, obeys, minimized))
            })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(domain, expected);
}

#[test]
fn missing_attacker_is_ignored_before_gate_and_required_after_gate() {
    let clear = BATTLE_SCRIPT_SETMINIMIZE_CASES
        .iter()
        .find(|case| case.label == "missing_attacker_not_obeys_succeeds")
        .expect("missing OBEYS-clear missing-attacker vector");
    assert_eq!(clear.initial.attacker, None);
    assert_eq!(clear.initial.hit_marker & BATTLE_SCRIPT_HITMARKER_OBEYS, 0);
    assert_eq!(clear.expected, Some(clear.initial));
    assert_eq!(clear.expected_error, None);

    let set = BATTLE_SCRIPT_SETMINIMIZE_CASES
        .iter()
        .find(|case| case.label == "missing_attacker_obeys_errors")
        .expect("missing OBEYS-set missing-attacker vector");
    assert_eq!(set.initial.attacker, None);
    assert_ne!(set.initial.hit_marker & BATTLE_SCRIPT_HITMARKER_OBEYS, 0);
    assert_eq!(set.expected, None);
    assert_eq!(
        set.expected_error,
        Some("Battle Script hit-chain command requires a attacker role"),
    );

    let repeated = BATTLE_SCRIPT_SETMINIMIZE_CASES
        .iter()
        .find(|case| case.category == "repeated-application")
        .expect("missing canonical repeated-application vector");
    assert_eq!(repeated.applications, 2);
}

#[test]
fn fixed_domains_u32_edges_and_source_constants_are_retained() {
    assert_eq!(BATTLE_SCRIPT_SETMINIMIZE_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_SETMINIMIZE_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_SETMINIMIZE_BATTLER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_SETMINIMIZE_BATTLER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(
        BATTLE_SCRIPT_SETMINIMIZE_STATUS3_EDGE_DOMAIN,
        [0x0000_0000, u32::MAX, 0x8000_0000, 0x0000_0001],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETMINIMIZE_HIT_MARKER_EDGE_DOMAIN,
        [0x0000_0000, u32::MAX, 0x8000_0000, 0x0100_0001],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETMINIMIZE_MINIMIZED_INPUT_DOMAIN,
        [0x0000_0000, 0x0000_0100],
    );
    assert_eq!(BATTLE_SCRIPT_STATUS3_MINIMIZED, 0x0000_0100);
    assert_eq!(BATTLE_SCRIPT_HITMARKER_OBEYS, 0x0200_0000);
}

#[test]
fn domain_category_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(
        BATTLE_SCRIPT_SETMINIMIZE_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("attacker-role-values", 4),
            ("optional-attacker-role-values", 5),
            ("status3-u32-values", 4_294_967_296),
            ("hitmarker-u32-values", 4_294_967_296),
            ("status3-edge-values", 4),
            ("hitmarker-edge-values", 4),
            ("obeys-gate-values", 2),
            ("minimized-clear-set-inputs", 2),
            ("application-count-values", 2),
            ("typed-missing-role-gate-combinations", 2),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETMINIMIZE_CATEGORY_CENSUS,
        [
            ("attacker-gate-minimized-matrix", 16),
            ("hitmarker-u32-edge-matrix", 16),
            ("missing-attacker-gate-ordering", 2),
            ("repeated-application", 1),
            ("status3-u32-edge-matrix", 16),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETMINIMIZE_BRANCH_CENSUS,
        [
            ("missing-attacker-role", 1),
            ("obeys-clear-noop", 21),
            ("set-attacker-minimized", 29),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETMINIMIZE_VECTOR_CORPUS_SHA256,
        "d3760ba077c31a99adb30d27642450f8de055ca72a00abed711bf91f0e334a49",
    );
}
